effect.shader:
#define PI 3.14159265359
vec2 hash22(vec2 p) {
vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
p3 += dot(p3, p3.yzx + 33.33);
return fract((p3.xx + p3.yz) * p3.zy);
}
void main() {
vec2 uv = acScreenNorm;
float aspect = acScreenSize.x / max(acScreenSize.y, 1.0);
vec2 st = uv;
st.x *= aspect;
float t = acTime * speed;
vec2 totalDistortion = vec2(0.0);
for(float i = 0.0; i < 3.0; i++) {
float layerTime = t + i * 1.5;
float timeInt = floor(layerTime);
float timeFrac = fract(layerTime);
vec2 gridCenter = vec2(0.5 * aspect, 0.5);
vec2 randPos = hash22(vec2(timeInt, i)) * density;
vec2 gv = st * density - randPos;
vec2 id = floor(gv);
vec2 fv = fract(gv) - 0.5;
float d = length(fv);
float maxRadius = 0.5;
float currentRadius = timeFrac * maxRadius;
if (d < currentRadius && d > currentRadius - 0.2) {
float ringPos = (d - (currentRadius - 0.2)) / 0.2;
float wave = sin(ringPos * frequency * PI) * distortion;
float fade = exp(-currentRadius * decay);
vec2 dir = normalize(fv);
totalDistortion += dir * wave * fade;
}
}
vec2 distortedUv = uv + vec2(totalDistortion.x / aspect, totalDistortion.y);
vec4 finalColor = texture2DCv(inputImg.texture, clamp(distortedUv, 0.0, 1.0));
vec4 original = texture2DCv(inputImg.texture, uv);
gl_FragColor = mix(original, finalColor, alpha);
}
